    },
    {
      "item": "Q",
      "frame": "loki-front.png",
      "fix": "Match the Medusa reference's painted collectible miniature quality with sharper facial and hair sculpting, richer layered robe folds, subtle fabric texture and crisp Norse relief engraving on the gold armor.",
      "tool": "Codex 1a"
    },
    {
      "item": "P",
      "frame": "loki-front.png",
      "fix": "Use base colors #2F5A3A for the robe, #C9A24A for gold and #1E1C1E for hair, and restore a clearly distinct #6FE07A green magic accent instead of the muted olive wisps.",
      "tool": "Codex 1a"
    }
  ],
